<script setup lang="ts">import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import {fetchConsult} from '@/api/patient';const data=ref<any>(null);onLoad(async(q)=>{const id=Number(q?.id);if(!Number.isInteger(id)||id<=0){uni.showToast({title:'咨询不存在',icon:'none'});return}try{data.value=await fetchConsult(id)}catch(e:any){uni.showToast({title:e.message||'加载失败',icon:'none'})}})</script>
<template><view class="page" v-if="data"><view class="card"><text class="title">{{data.doctor_name}} · {{data.status===2?'已关闭':'处理中'}}</text></view><view v-for="(item,index) in data.timeline" :key="index" class="card"><text class="role">{{item.type==='reply'?'医生回复':item.type==='followup'?'患者追问':'初始咨询'}}</text><text class="content">{{item.content}}</text><text class="time">{{item.create_time}}</text></view></view></template>
<style scoped>.page{padding:24rpx}.card{background:#fff;border-radius:20rpx;padding:28rpx;margin-bottom:20rpx}.title,.role,.content,.time{display:block}.title,.role{font-weight:700}.content{margin-top:12rpx}.time{margin-top:12rpx;color:#999;font-size:22rpx}</style>
